import assert from "node:assert/strict";
import { readFile } from "node:fs/promises";
import { test } from "node:test";
import { PreviewRuntime } from "../test-dist/preview-runtime.mjs";
import { createPlatformerDemoProject } from "../test-dist/project-io.mjs";
import { rickCharacterForms } from "../test-dist/character-forms.mjs";

const width = 20, height = 10, collisions = Array(width * height).fill(0); for (let x = 0; x < width; ++x) collisions[8 * width + x] = 2;
const level = { map: { width, height, tileWidth: 8, tileHeight: 8, tileset: { tileCount: 1, columns: 1, image: "x" }, layers: { tiles: Array(width * height).fill(0), frontTiles: Array(width * height).fill(0), collisions } }, entities: { checkpoints: [{ pl_x: 16, pl_y: 43, pl_face: "right" }], platforms: [{ id: 1, attributes: { ini_x: 0, ini_y: 0, width: 8, height: 8, recursive: 1 }, actions: { action: [{ direction: "right", desp: 3, speed: 1, wait: 2 }, { direction: "left", desp: 3, speed: 1, wait: 0 }] } }], hazards: [] } };
test("preview advances deterministically in fixed ticks and reset is exact", () => { const runtime = new PreviewRuntime(level); for (let i = 0; i < 3; ++i) runtime.step(); assert.equal(runtime.bodies[0].x, 3); for (let i = 0; i < 3; ++i) runtime.step(); assert.equal(runtime.bodies[0].x, 0); runtime.reset(); assert.equal(runtime.tick, 0); assert.equal(runtime.bodies[0].x, 0); });
test("preview loads the character forms contract from runtimeProfile", () => { const data = structuredClone(level); const forms = rickCharacterForms(); forms.forms[0].id = "configured-rick"; forms.initialForm = "configured-rick"; data.runtimeProfile = { characterForms: forms }; const runtime = new PreviewRuntime(data); assert.equal(runtime.playerForm, "configured-rick"); });
test("preview renders and applies a generic form's definition, animation and physics", async () => { const data = structuredClone(level); data.runtimeProfile = { characterForms: JSON.parse(await readFile(new URL("../../tests/fixtures/character_forms.json", import.meta.url), "utf8")) }; const runtime = new PreviewRuntime(data); const right = { left: false, right: true, up: false, down: false, action: false }; for (let tick = 0; tick < 6; ++tick) runtime.step(right); assert.equal(runtime.playerForm, "frog"); assert.equal(runtime.player.collisionHeight, 31); const player = runtime.bodies.find((body) => body.key === "player"); assert.equal(player.definition, "characters/frog"); assert.equal(player.state, "FROG_IDLE"); });
test("runtime bodies expose semantic kinds independent from their stable keys", () => { const data = structuredClone(level); data.entities.items = [{ id: 4, attributes: { ini_x: 80, ini_y: 56, width: 8, height: 8 } }]; data.entities.blocks = [{ id: 5, attributes: { ini_x: 96, ini_y: 56, width: 8, height: 8 } }]; const runtime = new PreviewRuntime(data); const byKey = new Map(runtime.bodies.map((body) => [body.key, body.kind])); assert.equal(byKey.get("platforms:1"), "platform"); assert.equal(byKey.get("items:4"), "item"); assert.equal(byKey.get("blocks:5"), "block"); assert.equal(byKey.get("player"), "player"); });
test("wait is ignored after a movement action with non-zero displacement", () => { const data = structuredClone(level); data.entities.platforms = [{ id: 50, attributes: { ini_x: 80, ini_y: 8, width: 8, height: 8, recursive: 1 }, actions: { action: [{ direction: "right", desp: 2, speed: 1, wait: 10 }, { direction: "left", desp: 1, speed: 1, wait: 0 }] } }]; const runtime = new PreviewRuntime(data); runtime.step(); runtime.step(); assert.equal(runtime.bodies.find((body) => body.key === "platforms:50").x, 82); runtime.step(); assert.equal(runtime.bodies.find((body) => body.key === "platforms:50").x, 81); });
test("two runtimes produce identical snapshots", () => { const a = new PreviewRuntime(level); const b = new PreviewRuntime(level); for (let i = 0; i < 100; ++i) { a.step(); b.step(); } assert.deepEqual(a.bodies, b.bodies); });
test("camera views clamp the native viewport and resolve overlap by facing", () => { const data = structuredClone(level); data.camera = { width: 40, height: 30 }; data.entities.cameraViews = [{ id: 1, left_up_x: 0, left_up_y: 0, right_down_x: 80, right_down_y: 80 }, { id: 2, left_up_x: 40, left_up_y: 0, right_down_x: 120, right_down_y: 80 }]; data.entities.checkpoints[0] = { pl_x: 30, pl_y: 43, pl_face: "right" }; const right = new PreviewRuntime(data); assert.deepEqual(right.cameraFrame, { x: 40, y: 28, width: 40, height: 30, viewId: 2 }); data.entities.checkpoints[0].pl_face = "left"; const left = new PreviewRuntime(data); assert.equal(left.cameraFrame.viewId, 1); assert.equal(left.cameraFrame.x, 10); });
test("camera views can be disabled without changing level data", () => { const data = structuredClone(level); data.camera = { width: 40, height: 30 }; data.entities.cameraViews = [{ id: 3, left_up_x: 40, left_up_y: 0, right_down_x: 120, right_down_y: 80 }]; data.entities.checkpoints[0] = { pl_x: 50, pl_y: 43, pl_face: "right" }; const runtime = new PreviewRuntime(data); assert.equal(runtime.cameraFrame.x, 40); runtime.setCameraViewsEnabled(false); assert.equal(runtime.cameraViewsEnabled, false); assert.equal(runtime.cameraFrame.viewId, -1); assert.equal(runtime.cameraFrame.x, 30); assert.equal(data.entities.cameraViews.length, 1); runtime.setCameraViewsEnabled(true); assert.equal(runtime.cameraFrame.viewId, 3); });
test("camera position remains frozen while Rick is dying", () => { const data = structuredClone(level); data.camera = { width: 40, height: 30 }; data.entities.hazards = [{ id: 12, attributes: { ini_x: 21, ini_y: 43, width: 13, height: 21, trigger: 1 }, actions: { action: { direction: "stop", desp: 0, speed: 0, wait: 0 } } }]; const runtime = new PreviewRuntime(data); const before = runtime.cameraFrame; runtime.step(); for (let i = 0; i < 10; ++i) runtime.step(); assert.deepEqual(runtime.cameraFrame, before); });
test("visible hazards kill the player and consume one life", () => { const data = structuredClone(level); data.entities.hazards = [{ id: 9, attributes: { ini_x: 21, ini_y: 43, width: 13, height: 21, trigger: 1 }, actions: { action: { direction: "stop", desp: 0, speed: 0, wait: 0 } } }]; const runtime = new PreviewRuntime(data); runtime.step(); assert.equal(runtime.player.state, "dead"); assert.equal(runtime.lives, 2); });
test("Rick's dying sprite grows without changing its collision box", () => { const data = structuredClone(level); data.entities.hazards = [{ id: 10, attributes: { ini_x: 21, ini_y: 43, width: 13, height: 21, trigger: 1 }, actions: { action: { direction: "stop", desp: 0, speed: 0, wait: 0 } } }]; const runtime = new PreviewRuntime(data); runtime.step(); runtime.step(); const body = runtime.bodies.find((candidate) => candidate.key === "player"); assert.equal(body.spriteScale, 1.1); assert.equal(body.width, 13); assert.equal(body.height, 21); });
test("preview accepts an injected platformer controller profile", () => { const runtime = new PreviewRuntime(level, { playerController: { collisionWidth: 7, collisionOffsetX: 1, runSpeed: 4 } }); runtime.step({ left: false, right: true, up: false, down: false, action: false }); assert.equal(runtime.player.x, 20); assert.equal(runtime.player.collisionX, 21); assert.equal(runtime.player.collisionWidth, 7); });
test("preview action bindings control which optional projectile is created", () => { const runtime = new PreviewRuntime(level, { playerActionBindings: { up: null, down: "shooting" } }); runtime.step({ left: false, right: false, up: false, down: true, action: true }); assert.equal(runtime.player.state, "shooting"); assert.equal(runtime.bodies.some((body) => body.key === "shoot:0"), true); assert.equal(runtime.bodies.some((body) => body.key === "bomb:0"), false); });
test("preview exposes configured animation states and audio slots", () => { const data = structuredClone(level); data.entities.blocks = [{ id: 20, attributes: { ini_x: 80, ini_y: 56, width: 8, height: 8 } }]; const runtime = new PreviewRuntime(data, { runtimeBindings: { playerStates: { shooting: "HERO_FIRE" }, objectStates: { stop: "IDLE", moving: "ACTIVE", dying: "DESTROYED" }, audio: { shot: 9 } } }); assert.equal(runtime.bodies.find((body) => body.key === "blocks:20").state, "IDLE"); runtime.step({ left: false, right: false, up: true, down: false, action: true }); assert.equal(runtime.bodies.find((body) => body.key === "player").state, "HERO_FIRE"); assert.equal(runtime.bodies.find((body) => body.key === "shoot:0").state, "ACTIVE"); assert.deepEqual(runtime.drainAudioEvents(), [9]); });
test("preview reads a runtime profile embedded in level data", () => { const data = structuredClone(level); data.runtimeProfile = { controller: { runSpeed: 4 }, capabilities: { bomb: false }, bindings: { playerStates: { running: "HERO_RUN" } } }; const runtime = new PreviewRuntime(data); runtime.step({ left: false, right: true, up: false, down: false, action: false }); assert.equal(runtime.player.x, 20); assert.equal(runtime.bodies.find((body) => body.key === "player").state, "HERO_RUN"); runtime.step({ left: false, right: false, up: false, down: true, action: true }); assert.equal(runtime.bodies.some((body) => body.kind === "bomb"), false); });
test("reach-zone objectives complete and optionally freeze simulation", () => { const data = structuredClone(level); data.objective = { type: "reachZone", x: 17, y: 43, width: 20, height: 21, onComplete: "freeze" }; const runtime = new PreviewRuntime(data); runtime.step(); assert.equal(runtime.completed, true); const tick = runtime.tick; runtime.step({ left: false, right: true, up: false, down: false, action: false }); assert.equal(runtime.tick, tick); runtime.reset(); assert.equal(runtime.completed, false); });
test("generic demo runs with non-Rick states and reaches its objective", () => { const project = createPlatformerDemoProject(); const data = JSON.parse(new TextDecoder().decode(project.files.get(project.manifest.initialLevel))); const runtime = new PreviewRuntime(data); runtime.setInvulnerable(true); for (let tick = 0; tick < 180 && !runtime.completed; ++tick) runtime.step({ left: false, right: true, up: false, down: false, action: false }); assert.equal(runtime.completed, true); assert.equal(runtime.bodies.find((body) => body.key === "player").state, "HERO_RUN"); assert.equal(runtime.bodies.find((body) => body.key === "enemies:0").state, "CRITTER_WALK"); });
test("invulnerable debug mode reports danger without killing the player", () => { const data = structuredClone(level); data.entities.hazards = [{ id: 9, attributes: { ini_x: 21, ini_y: 43, width: 13, height: 21, trigger: 1 }, actions: { action: { direction: "stop", desp: 0, speed: 0, wait: 0 } } }]; const runtime = new PreviewRuntime(data); runtime.setInvulnerable(true); runtime.step(); assert.equal(runtime.player.state, "stop"); assert.equal(runtime.dangerContact, true); });
test("session rules can report danger without applying damage", () => { const data = structuredClone(level); data.entities.hazards = [{ id: 9, attributes: { ini_x: 21, ini_y: 43, width: 13, height: 21, trigger: 1 }, actions: { action: { direction: "stop", desp: 0, speed: 0, wait: 0 } } }]; const runtime = new PreviewRuntime(data, { sessionRules: { damageEnabled: false } }); runtime.step(); assert.equal(runtime.player.state, "stop"); assert.equal(runtime.dangerContact, true); assert.equal(runtime.lives, 3); });
test("a no-respawn session ends on its first death", () => { const data = structuredClone(level); data.entities.hazards = [{ id: 9, attributes: { ini_x: 21, ini_y: 43, width: 13, height: 21, trigger: 1 }, actions: { action: { direction: "stop", desp: 0, speed: 0, wait: 0 } } }]; const runtime = new PreviewRuntime(data, { sessionRules: { respawn: "none", deathAudioSlot: null } }); runtime.step(); assert.equal(runtime.lives, 2); assert.equal(runtime.gameOver, true); assert.deepEqual(runtime.drainAudioEvents(), []); });
test("the final life enters game over until reset", () => { const data = structuredClone(level); data.session = { initialLives: 1 }; data.entities.hazards = [{ id: 9, attributes: { ini_x: 21, ini_y: 43, width: 13, height: 21, trigger: 1 }, actions: { action: { direction: "stop", desp: 0, speed: 0, wait: 0 } } }]; const runtime = new PreviewRuntime(data); runtime.step(); assert.equal(runtime.lives, 0); assert.equal(runtime.gameOver, true); for (let i = 0; i < 30; ++i) runtime.step(); assert.equal(runtime.player.state, "dead"); runtime.reset(); assert.equal(runtime.lives, 1); assert.equal(runtime.gameOver, false); assert.equal(runtime.player.state, "stop"); });
test("deactivated hazards are neither rendered nor lethal", () => { const data = structuredClone(level); data.entities.hazards = [{ id: 9, attributes: { ini_x: 21, ini_y: 43, width: 13, height: 21, trigger: 1 }, actions: { action: { direction: "deactivate", desp: 0, speed: 0, wait: 20 } } }]; const runtime = new PreviewRuntime(data); runtime.step(); assert.equal(runtime.player.state, "stop"); assert.equal(runtime.bodies.some((body) => body.key === "hazards:9"), false); });
test("waiting hazards select their STOP animation state", () => { const data = structuredClone(level); data.entities.hazards = [{ id: 10, attributes: { ini_x: 80, ini_y: 8, width: 8, height: 8, trigger: 1 }, actions: { action: { direction: "stop", desp: 0, speed: 0, wait: 20 } } }]; const runtime = new PreviewRuntime(data); runtime.setInvulnerable(true); runtime.step(); assert.equal(runtime.bodies.find((body) => body.key === "hazards:10").state, "OBJ_STATE_STOP"); });
test("only lasers enabled by default are initially lethal", () => { const data = structuredClone(level); data.entities.lasers = [{ id: 1, x: 16, y: 40, bb_x: 5, bb_y: 3, bb_width: 13, bb_height: 21, default_trigger: 1 }, { id: 2, x: 16, y: 40, bb_x: 5, bb_y: 3, bb_width: 13, bb_height: 21, default_trigger: 0 }]; const runtime = new PreviewRuntime(data); runtime.step(); assert.equal(runtime.player.state, "dead"); assert.equal(runtime.bodies.some((body) => body.key === "lasers:1"), true); assert.equal(runtime.bodies.some((body) => body.key === "lasers:2"), false); });
test("active lasers move according to type, speed and direction", () => { const data = structuredClone(level); data.entities.lasers = [{ id: 3, x: 80, y: 8, bb_x: 0, bb_y: 0, bb_width: 4, bb_height: 4, type: "diagonal", speed: 3, direction: "left", default_trigger: 1 }]; const runtime = new PreviewRuntime(data); runtime.setInvulnerable(true); runtime.step(); const laser = runtime.bodies.find((body) => body.key === "lasers:3"); assert.equal(laser.x, 77); assert.equal(laser.y, 11); });
test("default lasers play DYING and reset at their origin after colliding with the map", () => { const data = structuredClone(level); data.entities.lasers = [{ id: 4, x: 40, y: 55, bb_x: 0, bb_y: 0, bb_width: 4, bb_height: 4, type: "vertical", speed: 2, direction: "right", default_trigger: 1 }]; const runtime = new PreviewRuntime(data); runtime.step(); runtime.step(); runtime.step(); assert.equal(runtime.bodies.find((body) => body.key === "lasers:4").state, "OBJ_STATE_DYING"); runtime.step(); assert.equal(runtime.bodies.some((body) => body.key === "lasers:4"), false); runtime.step(); const laser = runtime.bodies.find((body) => body.key === "lasers:4"); assert.equal(laser.x, 40); assert.equal(laser.y, 57); });
test("active lasers kill enemies without stopping their trajectory", () => { const data = structuredClone(level); data.entities.lasers = [{ id: 32, x: 40, y: 51, bb_x: 0, bb_y: 0, bb_width: 4, bb_height: 6, type: "horizontal", speed: 4, direction: "right", default_trigger: 1 }]; data.entities.enemies = [{ id: 32, x: 44, y: 51, bb_x: 0, bb_y: 0, bb_width: 8, bb_height: 8, direction: "right", speed_x: 0, speed_y: 0, ia_type: "walker" }]; const runtime = new PreviewRuntime(data); runtime.setInvulnerable(true); runtime.step(); assert.equal(runtime.bodies.some((body) => body.key === "enemies:32"), false); assert.equal(runtime.bodies.find((body) => body.key === "lasers:32").x, 44); });
test("enter triggers launch inactive lasers after their configured delay", () => { const data = structuredClone(level); data.entities.lasers = [{ id: 5, x: 80, y: 8, bb_x: 0, bb_y: 0, bb_width: 4, bb_height: 4, type: "horizontal", speed: 1, direction: "right", default_trigger: 0 }]; data.entities.triggers = [{ attributes: { x: 16, y: 43, width: 23, height: 21, action: "enters", face: "any", recursive: 0 }, targets: { target: { type: "laser", id: 5, delay: 2, trigger: 1, trigger_cond: 0 } } }]; const runtime = new PreviewRuntime(data); runtime.step(); runtime.step(); runtime.step(); assert.equal(runtime.bodies.some((body) => body.key === "lasers:5"), false); runtime.step(); assert.equal(runtime.bodies.some((body) => body.key === "lasers:5"), true); });
test("trigger face is respected", () => { const data = structuredClone(level); data.entities.lasers = [{ id: 6, x: 80, y: 8, bb_x: 0, bb_y: 0, bb_width: 4, bb_height: 4, type: "horizontal", speed: 1, direction: "right", default_trigger: 0 }]; data.entities.triggers = [{ attributes: { x: 16, y: 43, width: 23, height: 21, action: "enters", face: "left", recursive: 0 }, targets: { target: { type: "laser", id: 6, delay: 0, trigger: 1, trigger_cond: 0 } } }]; const runtime = new PreviewRuntime(data); runtime.step(); runtime.step(); assert.equal(runtime.bodies.some((body) => body.key === "lasers:6"), false); });
test("hit triggers use a fresh horizontal action press while the player stays inside", () => { const data = structuredClone(level); data.entities.lasers = [{ id: 7, x: 80, y: 8, bb_x: 0, bb_y: 0, bb_width: 4, bb_height: 4, type: "horizontal", speed: 1, direction: "right", default_trigger: 0 }]; data.entities.triggers = [{ attributes: { x: 16, y: 43, width: 40, height: 21, action: "hits", face: "right", recursive: 0 }, targets: { target: { type: "laser", id: 7, delay: 0, trigger: 1, trigger_cond: 0 } } }]; const runtime = new PreviewRuntime(data); runtime.step(); runtime.step({ left: false, right: true, up: false, down: false, action: true }); assert.equal(runtime.bodies.some((body) => body.key === "lasers:7"), false); runtime.step(); assert.equal(runtime.bodies.some((body) => body.key === "lasers:7"), true); });
test("hit triggers ignore action keys when Rick cannot enter HITTING", () => { const data = structuredClone(level); data.entities.checkpoints[0].pl_y = 20; data.entities.lasers = [{ id: 8, x: 80, y: 8, bb_x: 0, bb_y: 0, bb_width: 4, bb_height: 4, type: "horizontal", speed: 1, direction: "right", default_trigger: 0 }]; data.entities.triggers = [{ attributes: { x: 0, y: 0, width: 80, height: 64, action: "hits", face: "right", recursive: 0 }, targets: { target: { type: "laser", id: 8, delay: 0, trigger: 1, trigger_cond: 0 } } }]; const runtime = new PreviewRuntime(data); runtime.step(); runtime.step({ left: false, right: true, up: false, down: false, action: true }); runtime.step(); assert.equal(runtime.player.state, "jumping"); assert.equal(runtime.bodies.some((body) => body.key === "lasers:8"), false); });
test("stopped platforms wait until a trigger starts their sequence", () => { const data = structuredClone(level); data.entities.platforms = [{ id: 8, attributes: { ini_x: 80, ini_y: 8, width: 8, height: 8, ini_state: "stop", recursive: 0, visible: 1 }, actions: { action: { direction: "right", desp: 8, speed: 2, wait: 0, cond: 0 } } }]; data.entities.triggers = [{ attributes: { x: 16, y: 43, width: 23, height: 21, action: "enters", face: "any", recursive: 0 }, targets: { target: { type: "platform", id: 8, delay: 0, trigger: 1, trigger_cond: 0 } } }]; const runtime = new PreviewRuntime(data); runtime.step(); assert.equal(runtime.bodies.find((body) => body.key === "platforms:8").x, 80); runtime.step(); runtime.step(); assert.equal(runtime.bodies.find((body) => body.key === "platforms:8").x, 82); });
test("trigger false toggles conditions without stopping a moving platform", () => { const data = structuredClone(level); data.entities.platforms = [{ id: 20, attributes: { ini_x: 80, ini_y: 8, width: 8, height: 8, ini_state: "moving", recursive: 1, visible: 1 }, actions: { action: { direction: "right", desp: 20, speed: 1, wait: 0, cond: 0 } } }]; data.entities.triggers = [{ attributes: { x: 16, y: 43, width: 23, height: 21, action: "enters", face: "any", recursive: 0 }, targets: { target: { type: "platform", id: 20, delay: 0, trigger: 0, trigger_cond: 1 } } }]; const runtime = new PreviewRuntime(data); runtime.step(); runtime.step(); runtime.step(); assert.equal(runtime.bodies.find((body) => body.key === "platforms:20").x, 83); });
test("trigger_cond switches a recursive platform to its enabled branch", () => { const data = structuredClone(level); data.entities.platforms = [{ id: 21, attributes: { ini_x: 80, ini_y: 8, width: 8, height: 8, ini_state: "moving", recursive: 1, visible: 1 }, actions: { action: [{ direction: "right", desp: 2, speed: 1, wait: 0, cond: 2 }, { direction: "left", desp: 2, speed: 1, wait: 0, cond: 1 }] } }]; data.entities.triggers = [{ attributes: { x: 16, y: 43, width: 23, height: 21, action: "enters", face: "any", recursive: 0 }, targets: { target: { type: "platform", id: 21, delay: 0, trigger: 0, trigger_cond: 1 } } }]; const runtime = new PreviewRuntime(data); runtime.step(); runtime.step(); runtime.step(); assert.equal(runtime.bodies.find((body) => body.key === "platforms:21").x, 81); });
test("one-use platforms cannot be restarted by a recursive trigger", () => { const data = structuredClone(level); data.entities.platforms = [{ id: 22, attributes: { ini_x: 80, ini_y: 8, width: 8, height: 8, ini_state: "stop", recursive: 0, one_use: 1, visible: 1 }, actions: { action: { direction: "right", desp: 2, speed: 1, wait: 0, cond: 0 } } }]; data.entities.triggers = [{ attributes: { x: 16, y: 43, width: 23, height: 21, action: "enters", face: "any", recursive: 1 }, targets: { target: { type: "platform", id: 22, delay: 0, trigger: 1, trigger_cond: 0 } } }]; const runtime = new PreviewRuntime(data); for (let i = 0; i < 12; ++i) runtime.step(); assert.equal(runtime.bodies.find((body) => body.key === "platforms:22").x, 82); });
test("completed stop-inactive hazards become hidden and harmless", () => { const data = structuredClone(level); data.entities.hazards = [{ id: 23, attributes: { ini_x: 21, ini_y: 43, width: 13, height: 21, trigger: 0, stop_inactive: 1 }, actions: { action: { direction: "right", desp: 1, speed: 1, wait: 0, cond: 0 } } }]; data.entities.triggers = [{ attributes: { x: 16, y: 43, width: 23, height: 21, action: "enters", face: "any", recursive: 0 }, targets: { target: { type: "hazard", id: 23, delay: 0, trigger: 1, trigger_cond: 0 } } }]; const runtime = new PreviewRuntime(data); runtime.setInvulnerable(true); for (let i = 0; i < 4; ++i) runtime.step(); assert.equal(runtime.bodies.some((body) => body.key === "hazards:23"), false); assert.equal(runtime.player.state, "stop"); assert.equal(runtime.dangerContact, false); });
test("a terminal stop action remains active for its complete wait", () => { const data = structuredClone(level); data.entities.hazards = [{ id: 24, attributes: { ini_x: 21, ini_y: 43, width: 13, height: 21, trigger: 0, stop_inactive: 0 }, actions: { action: { direction: "stop", desp: 0, speed: 0, wait: 2, cond: 0 } } }]; data.entities.triggers = [{ attributes: { x: 16, y: 43, width: 23, height: 21, action: "enters", face: "any", recursive: 0 }, targets: { target: { type: "hazard", id: 24, delay: 0, trigger: 1, trigger_cond: 0 } } }]; const runtime = new PreviewRuntime(data); runtime.setInvulnerable(true); runtime.step(); runtime.step(); runtime.step(); assert.equal(runtime.dangerContact, true); runtime.step(); assert.equal(runtime.dangerContact, true); runtime.step(); assert.equal(runtime.dangerContact, false); });
test("recursive triggers do not restart a laser that is still travelling", () => { const data = structuredClone(level); data.entities.lasers = [{ id: 9, x: 80, y: 8, bb_x: 0, bb_y: 0, bb_width: 4, bb_height: 4, type: "horizontal", speed: 1, direction: "right", default_trigger: 0 }]; data.entities.triggers = [{ attributes: { x: 16, y: 43, width: 23, height: 21, action: "enters", face: "any", recursive: 1 }, targets: { target: { type: "laser", id: 9, delay: 0, trigger: 1, trigger_cond: 0 } } }]; const runtime = new PreviewRuntime(data); runtime.setInvulnerable(true); for (let i = 0; i < 8; ++i) runtime.step(); assert.ok(runtime.bodies.find((body) => body.key === "lasers:9").x >= 85); });
test("a recursive laser keeps relaunching after its first external trigger", () => { const data = structuredClone(level); data.entities.lasers = [{ id: 10, x: 40, y: 55, bb_x: 0, bb_y: 0, bb_width: 4, bb_height: 4, type: "vertical", recursive: 1, speed: 2, direction: "right", default_trigger: 0 }]; data.entities.triggers = [{ attributes: { x: 16, y: 43, width: 23, height: 21, action: "enters", face: "any", recursive: 0 }, targets: { target: { type: "laser", id: 10, delay: 0, trigger: 1, trigger_cond: 0 } } }]; const runtime = new PreviewRuntime(data); runtime.setInvulnerable(true); for (let i = 0; i < 7; ++i) runtime.step(); const laser = runtime.bodies.find((body) => body.key === "lasers:10"); assert.equal(laser.state, "OBJ_STATE_MOVING"); assert.equal(laser.y, 57); });
test("shooting creates one projectile that advances at native speed", () => { const runtime = new PreviewRuntime(level), input = { left: false, right: false, up: true, down: false, action: true }; runtime.step(input); const start = runtime.bodies.find((body) => body.key === "shoot:0").x; runtime.step(input); assert.equal(runtime.bodies.filter((body) => body.key === "shoot:0").length, 1); assert.equal(runtime.bodies.find((body) => body.key === "shoot:0").x, start + 4); });
test("runtime bodies expose animation state and native sound slots", () => { const data = structuredClone(level); data.player = { definition: "characters/rick" }; data.projectiles = { shoot: { definition: "designs/shoot/shoot", width: 12, height: 6 }, bomb: {} }; const runtime = new PreviewRuntime(data); runtime.step({ left: false, right: false, up: true, down: false, action: true }); const player = runtime.bodies.find((body) => body.key === "player"), shot = runtime.bodies.find((body) => body.key === "shoot:0"); assert.equal(player.definition, "characters/rick"); assert.equal(player.state, "RICK_STATE_SHOOTING"); assert.equal(shot.definition, "designs/shoot/shoot"); assert.deepEqual(runtime.drainAudioEvents(), [1]); assert.deepEqual(runtime.drainAudioEvents(), []); });
test("crouching marks its animation as one-shot", () => { const runtime = new PreviewRuntime(level); runtime.step({ left: false, right: false, up: false, down: true, action: false }); const player = runtime.bodies.find((body) => body.key === "player"); assert.equal(player.state, "RICK_STATE_CROUCHING"); assert.equal(player.animationOnce, true); assert.equal(player.height, 15); });
test("walking while crouched keeps the crouch animation cycling", () => { const runtime = new PreviewRuntime(level); const crouchRight = { left: false, right: true, up: false, down: true, action: false }; runtime.step(crouchRight); let player = runtime.bodies.find((body) => body.key === "player"); assert.equal(player.state, "RICK_STATE_CROUCHING"); assert.equal(player.animationOnce, false); runtime.step(crouchRight); player = runtime.bodies.find((body) => body.key === "player"); assert.ok(player.frame > 0); assert.equal(player.animationOnce, false); });
test("bomb fuse and explosion duration come from the animation definition", () => { const data = structuredClone(level); data.definitions = { bomb: { states: [{ name: "OBJ_STATE_MOVING", animation: { frameDurationTicks: 2, sprites: [{}, {}] } }, { name: "OBJ_STATE_DYING", animation: { frameDurationTicks: 3, sprites: [{}] } }] } }; data.projectiles = { bomb: { definition: "bomb", width: 25, height: 22, yOffset: -1, boundingBox: { x: 8, y: 10, width: 10, height: 13 } }, shoot: { width: 12, height: 6, yOffset: 0 } }; const runtime = new PreviewRuntime(data); runtime.setInvulnerable(true); runtime.step({ left: false, right: false, up: false, down: true, action: true }); assert.equal(runtime.bodies.some((body) => body.key === "bomb:0"), true); for (let i = 0; i < 7; ++i) runtime.step(); assert.equal(runtime.bodies.some((body) => body.key === "bomb:0"), false); });
test("bombs retain horizontal throw speed while resting on the floor", () => { const data = structuredClone(level); data.projectiles = { bomb: { width: 25, height: 22, yOffset: -1, boundingBox: { x: 8, y: 10, width: 10, height: 13 } }, shoot: { width: 12, height: 6, yOffset: 0 } }; const runtime = new PreviewRuntime(data); runtime.setInvulnerable(true); const throwRight = { left: false, right: true, up: false, down: true, action: true }; runtime.step(throwRight); const start = runtime.bodies.find((body) => body.key === "bomb:0").x; runtime.step(throwRight); assert.equal(runtime.bodies.find((body) => body.key === "bomb:0").x, start + 1); });
test("bombs land on one-way platform tiles without treating them as walls", () => { const data = structuredClone(level); data.entities.checkpoints[0].pl_y = 19; for (const column of [2, 3, 4]) data.map.layers.collisions[5 * width + column] = 3; data.projectiles = { bomb: { width: 25, height: 22, yOffset: -1, boundingBox: { x: 8, y: 10, width: 10, height: 13 } }, shoot: {} }; const runtime = new PreviewRuntime(data); runtime.setInvulnerable(true); runtime.step({ left: false, right: false, up: false, down: true, action: true }); for (let i = 0; i < 5; ++i) runtime.step(); const bomb = runtime.bodies.find((body) => body.key === "bomb:0"); assert.equal(bomb.y, 18); assert.equal(bomb.x, 16); });
test("moving platforms carry resting bombs after updating their own position", () => { const data = structuredClone(level); data.entities.checkpoints[0].pl_y = 19; data.entities.platforms = [{ id: 40, attributes: { ini_x: 16, ini_y: 40, width: 32, height: 8, recursive: 1 }, actions: { action: [{ direction: "right", desp: 8, speed: 2, wait: 0 }, { direction: "left", desp: 8, speed: 2, wait: 0 }] } }]; data.projectiles = { bomb: { width: 25, height: 22, yOffset: -1, boundingBox: { x: 8, y: 10, width: 10, height: 13 } }, shoot: {} }; const runtime = new PreviewRuntime(data); runtime.setInvulnerable(true); runtime.step({ left: false, right: false, up: false, down: true, action: true }); const startX = runtime.bodies.find((body) => body.key === "bomb:0").x; runtime.step(); const carried = runtime.bodies.find((body) => body.key === "bomb:0"); assert.equal(carried.x, startX + 1); assert.equal(carried.y, 18); });
test("a thrown bomb stops when its collision box reaches a block", () => { const data = structuredClone(level); data.projectiles = { bomb: { width: 25, height: 22, yOffset: -1, boundingBox: { x: 8, y: 10, width: 10, height: 13 } }, shoot: {} }; data.entities.blocks = [{ id: 9, attributes: { ini_x: 34, ini_y: 51, width: 8, height: 13 } }]; const runtime = new PreviewRuntime(data); runtime.setInvulnerable(true); const throwRight = { left: false, right: true, up: false, down: true, action: true }; runtime.step(throwRight); for (let i = 0; i < 5; ++i) runtime.step(throwRight); assert.equal(runtime.bodies.find((body) => body.key === "bomb:0").x, 17); });
test("a bomb destroys the adjacent block that stopped it", () => { const data = structuredClone(level); data.definitions = { bomb: { states: [{ name: "OBJ_STATE_MOVING", animation: { frameDurationTicks: 1, sprites: [{}, {}, {}, {}] } }, { name: "OBJ_STATE_DYING", animation: { frameDurationTicks: 1, sprites: [{}] } }] } }; data.projectiles = { bomb: { definition: "bomb", width: 25, height: 22, yOffset: -1, boundingBox: { x: 8, y: 10, width: 10, height: 13 } }, shoot: {} }; data.entities.blocks = [{ id: 11, attributes: { ini_x: 34, ini_y: 51, width: 8, height: 13, exploits: 1 } }]; const runtime = new PreviewRuntime(data); runtime.setInvulnerable(true); const throwRight = { left: false, right: true, up: false, down: true, action: true }; runtime.step(throwRight); for (let i = 0; i < 5; ++i) runtime.step(throwRight); assert.equal(runtime.bodies.some((body) => body.key === "blocks:11"), false); });
test("shots collect items but stop harmlessly against blocks", () => { const data = structuredClone(level); data.projectiles = { shoot: { width: 12, height: 6, yOffset: 0 }, bomb: {} }; data.entities.items = [{ id: 1, attributes: { ini_x: 43, ini_y: 56, width: 8, height: 8 } }]; data.entities.blocks = [{ id: 2, attributes: { ini_x: 70, ini_y: 51, width: 8, height: 8 } }]; const runtime = new PreviewRuntime(data); const shoot = { left: false, right: false, up: true, down: false, action: true }; runtime.step(shoot); runtime.step(); assert.equal(runtime.bodies.some((body) => body.key === "items:1"), false); assert.equal(runtime.bodies.some((body) => body.key === "shoot:0"), false); assert.equal(runtime.bodies.some((body) => body.key === "blocks:2"), true); });
test("bomb explosions remove overlapping items, blocks and enemies", () => { const data = structuredClone(level); data.definitions = { bomb: { states: [{ name: "OBJ_STATE_MOVING", animation: { frameDurationTicks: 1, sprites: [{}] } }, { name: "OBJ_STATE_DYING", animation: { frameDurationTicks: 2, sprites: [{}] } }] } }; data.projectiles = { bomb: { definition: "bomb", width: 25, height: 22, yOffset: -1, boundingBox: { x: 8, y: 10, width: 10, height: 13 } }, shoot: {} }; data.entities.items = [{ id: 1, attributes: { ini_x: 23, ini_y: 51, width: 8, height: 8 } }]; data.entities.blocks = [{ id: 2, attributes: { ini_x: 30, ini_y: 51, width: 8, height: 8 } }]; data.entities.enemies = [{ id: 3, x: 25, y: 51, bb_x: 0, bb_y: 0, bb_width: 8, bb_height: 8, direction: "right", speed_x: 0, speed_y: 0, ia_type: "walker" }]; const runtime = new PreviewRuntime(data); runtime.setInvulnerable(true); runtime.step({ left: false, right: false, up: false, down: true, action: true }); runtime.step(); assert.equal(runtime.bodies.some((body) => body.key === "items:1"), false); assert.equal(runtime.bodies.some((body) => body.key === "blocks:2"), false); assert.equal(runtime.bodies.some((body) => body.key === "enemies:3"), false); });
test("non-explosive blocks are launched left for one camera width", () => { const data = structuredClone(level); data.camera = { width: 20, height: 80 }; data.definitions = { bomb: { states: [{ name: "OBJ_STATE_MOVING", animation: { frameDurationTicks: 1, sprites: [{}] }, }, { name: "OBJ_STATE_DYING", animation: { frameDurationTicks: 2, sprites: [{}] } }] } }; data.projectiles = { bomb: { definition: "bomb", width: 25, height: 22, yOffset: -1, boundingBox: { x: 8, y: 10, width: 10, height: 13 } }, shoot: {} }; data.entities.blocks = [{ id: 5, attributes: { ini_x: 30, ini_y: 51, width: 8, height: 8, exploits: 0 } }]; const runtime = new PreviewRuntime(data); runtime.setInvulnerable(true); runtime.step({ left: false, right: false, up: false, down: true, action: true }); runtime.step(); assert.equal(runtime.bodies.find((body) => body.key === "blocks:5").x, 30); runtime.step(); assert.equal(runtime.bodies.find((body) => body.key === "blocks:5").x, 20); runtime.step(); assert.equal(runtime.bodies.some((body) => body.key === "blocks:5"), false); });
test("visible resting blocks stop Rick horizontally", () => { const data = structuredClone(level); data.entities.blocks = [{ id: 6, attributes: { ini_x: 40, ini_y: 43, width: 8, height: 21 } }]; const runtime = new PreviewRuntime(data); const right = { left: false, right: true, up: false, down: false, action: false }; for (let i = 0; i < 20; ++i) runtime.step(right); assert.equal(runtime.player.x, 22); });
test("invulnerable debug mode lets Rick pass through blocks", () => { const data = structuredClone(level); data.entities.blocks = [{ id: 8, attributes: { ini_x: 40, ini_y: 43, width: 8, height: 21 } }]; const runtime = new PreviewRuntime(data); runtime.setInvulnerable(true); const right = { left: false, right: true, up: false, down: false, action: false }; for (let i = 0; i < 20; ++i) runtime.step(right); assert.ok(runtime.player.x > 40); assert.equal(runtime.bodies.some((body) => body.key === "blocks:8"), true); });
test("Rick can stand and jump from a resting block", () => { const data = structuredClone(level); data.entities.checkpoints[0].pl_y = 19; data.entities.blocks = [{ id: 7, attributes: { ini_x: 16, ini_y: 40, width: 32, height: 8 } }]; const runtime = new PreviewRuntime(data); runtime.step({ left: false, right: false, up: true, down: false, action: false }); assert.equal(runtime.player.state, "jumping"); assert.ok(runtime.player.y < 19); });
test("player contact collects visible items", () => { const data = structuredClone(level); data.entities.items = [{ id: 3, attributes: { ini_x: 21, ini_y: 43, width: 8, height: 8 } }]; const runtime = new PreviewRuntime(data); runtime.step(); assert.equal(runtime.bodies.some((body) => body.key === "items:3"), false); });
test("unsupported items fall and snap to the first traversable floor", () => { const data = structuredClone(level); data.entities.items = [{ id: 30, attributes: { ini_x: 80, ini_y: 20, width: 8, height: 8 } }]; const runtime = new PreviewRuntime(data); runtime.step(); assert.equal(runtime.bodies.find((body) => body.key === "items:30").state, "OBJ_STATE_MOVING"); for (let i = 0; i < 30; ++i) runtime.step(); const item = runtime.bodies.find((body) => body.key === "items:30"); assert.equal(item.y, 56); assert.equal(item.state, "OBJ_STATE_STOP"); });
test("supported items remain at their authored position", () => { const data = structuredClone(level); data.entities.items = [{ id: 31, attributes: { ini_x: 80, ini_y: 56, width: 8, height: 8 } }]; const runtime = new PreviewRuntime(data); for (let i = 0; i < 10; ++i) runtime.step(); const item = runtime.bodies.find((body) => body.key === "items:31"); assert.equal(item.y, 56); assert.equal(item.state, "OBJ_STATE_STOP"); });
test("bonus pickup rises at native speed during its disappearance transition", () => { const data = structuredClone(level); data.definitions = { "designs/items/bonus": { states: [{ name: "OBJ_STATE_DYING", animation: { frameDurationTicks: 1, sprites: [{}, {}] } }] } }; data.entities.items = [{ id: 4, attributes: { ini_x: 21, ini_y: 43, width: 8, height: 8, definition: "designs/items/bonus" } }]; const runtime = new PreviewRuntime(data); runtime.step(); assert.deepEqual(runtime.drainAudioEvents(), [4]); assert.equal(runtime.bodies.find((body) => body.key === "items:4").state, "OBJ_STATE_DYING"); runtime.step(); assert.equal(runtime.bodies.find((body) => body.key === "items:4").y, 40); for (let i = 1; i < 30; ++i) runtime.step(); assert.equal(runtime.bodies.some((body) => body.key === "items:4"), false); });
test("pickup behavior comes from semantic definition data, not the asset path", () => { const data = structuredClone(level); data.definitions = { "custom/treasure": { name: "bonus", states: [] } }; data.entities.items = [{ id: 42, attributes: { ini_x: 21, ini_y: 43, width: 8, height: 8, definition: "custom/treasure" } }]; const runtime = new PreviewRuntime(data); runtime.step(); assert.deepEqual(runtime.drainAudioEvents(), [4]); const pickup = runtime.bodies.find((body) => body.key === "items:42"); assert.equal(pickup.state, "OBJ_STATE_DYING"); runtime.step(); assert.equal(runtime.bodies.find((body) => body.key === "items:42").y, 40); });
test("animated background objects use MOVING and advance without becoming obstacles", () => { const data = structuredClone(level); data.entities.backgroundObjects = [{ id: 6, attributes: { ini_x: 80, ini_y: 8, width: 8, height: 8, skip_num_anims: 2, definition: "background/light" } }]; const runtime = new PreviewRuntime(data); const start = runtime.bodies.find((body) => body.key === "backgroundObjects:6").frame; runtime.step(); const body = runtime.bodies.find((candidate) => candidate.key === "backgroundObjects:6"); assert.equal(body.state, "OBJ_STATE_MOVING"); assert.equal(body.frame, start + 1); assert.equal(runtime.dangerContact, false); });
test("walker enemies reverse at their configured patrol limit", () => { const data = structuredClone(level); data.entities.enemies = [{ id: 1, x: 40, y: 43, bb_x: 0, bb_y: 0, bb_width: 10, bb_height: 21, direction: "right", speed_x: 1, speed_y: 3, ia_type: "walker", ia_orig_x: 40, ia_orig_y: 0, ia_limit_x: 2, ia_limit_y: 0 }]; const runtime = new PreviewRuntime(data); runtime.setInvulnerable(true); runtime.step(); runtime.step(); assert.equal(runtime.bodies.find((body) => body.key === "enemies:1").x, 42); runtime.step(); assert.equal(runtime.bodies.find((body) => body.key === "enemies:1").x, 41); });
test("walker enemies reverse instead of crossing a resting block", () => { const data = structuredClone(level); data.entities.blocks = [{ id: 10, attributes: { ini_x: 51, ini_y: 43, width: 8, height: 21 } }]; data.entities.enemies = [{ id: 19, x: 40, y: 43, bb_x: 0, bb_y: 0, bb_width: 10, bb_height: 21, direction: "right", speed_x: 1, speed_y: 3, ia_type: "walker" }]; const runtime = new PreviewRuntime(data); runtime.setInvulnerable(true); for (let i = 0; i < 4; ++i) runtime.step(); assert.ok(runtime.bodies.find((body) => body.key === "enemies:19").x < 42); });
test("random enemy decisions are reproducible after reset", () => { const data = structuredClone(level); data.entities.enemies = [{ id: 11, x: 40, y: 43, bb_x: 0, bb_y: 0, bb_width: 10, bb_height: 21, direction: "right", speed_x: 1, speed_y: 3, ia_type: "walker", ia_random: 1, ia_randomness: 1, ia_block_steps: 3 }]; const runtime = new PreviewRuntime(data); runtime.setInvulnerable(true); runtime.step(); const first = runtime.bodies.find((body) => body.key === "enemies:11").x; runtime.reset(); runtime.setInvulnerable(true); runtime.step(); assert.equal(first, 39); assert.equal(runtime.bodies.find((body) => body.key === "enemies:11").x, first); });
test("unknown enemy AI is rejected explicitly", () => { const data = structuredClone(level); data.entities.enemies = [{ id: 12, x: 40, y: 43, bb_x: 0, bb_y: 0, bb_width: 10, bb_height: 21, direction: "right", speed_x: 1, speed_y: 3, ia_type: "flying" }]; assert.throws(() => new PreviewRuntime(data), /Unregistered enemy AI: flying/); });
test("chaser enemies pursue the player inside their IA zone", () => { const data = structuredClone(level); data.entities.enemies = [{ id: 2, x: 60, y: 43, bb_x: 0, bb_y: 0, bb_width: 10, bb_height: 21, direction: "right", speed_x: 1, speed_y: 3, ia_type: "chaser", ia_orig_x: 0, ia_orig_y: 0, ia_limit_x: 100, ia_limit_y: 100 }]; const runtime = new PreviewRuntime(data); runtime.setInvulnerable(true); runtime.step(); assert.equal(runtime.bodies.find((body) => body.key === "enemies:2").x, 59); });
test("an aligned chaser chooses left like the native runtime", () => { const data = structuredClone(level); data.entities.enemies = [{ id: 9, x: 16, y: 43, bb_x: 0, bb_y: 0, bb_width: 10, bb_height: 21, direction: "right", speed_x: 1, speed_y: 3, ia_type: "chaser", ia_orig_x: 0, ia_orig_y: 0, ia_limit_x: 100, ia_limit_y: 100 }]; const runtime = new PreviewRuntime(data); runtime.setInvulnerable(true); runtime.step(); assert.equal(runtime.bodies.find((body) => body.key === "enemies:9").x, 15); });
test("chaser enemies immediately walk away from an unsupported edge", () => { const data = structuredClone(level); data.map.layers.collisions[8 * width + 8] = 0; data.entities.enemies = [{ id: 8, x: 56, y: 43, bb_x: 0, bb_y: 0, bb_width: 8, bb_height: 21, direction: "right", speed_x: 1, speed_y: 3, ia_type: "chaser", ia_orig_x: 0, ia_orig_y: 0, ia_limit_x: 120, ia_limit_y: 100, ia_block_steps: 3 }]; const runtime = new PreviewRuntime(data); runtime.setInvulnerable(true); runtime.placePlayerAt(84, 64); runtime.step(); assert.equal(runtime.bodies.find((body) => body.key === "enemies:8").x, 55); runtime.step(); assert.equal(runtime.bodies.find((body) => body.key === "enemies:8").x, 54); });
test("chaser enemies descend stairs when the player is below", () => { const data = structuredClone(level); data.map.layers.collisions[7 * width + 7] = 4; data.map.layers.collisions[8 * width + 7] = 5; data.entities.enemies = [{ id: 6, x: 56, y: 43, bb_x: 0, bb_y: 0, bb_width: 8, bb_height: 21, direction: "right", speed_x: 1, speed_y: 3, ia_type: "chaser", ia_orig_x: 0, ia_orig_y: 0, ia_limit_x: 120, ia_limit_y: 100 }]; const runtime = new PreviewRuntime(data); runtime.setInvulnerable(true); runtime.placePlayerAt(60, 80); runtime.step(); const enemy = runtime.bodies.find((body) => body.key === "enemies:6"); assert.equal(enemy.x, 56); assert.equal(enemy.y, 45); });
test("climbing animation advances vertically and rests at its first frame", () => { const data = structuredClone(level); data.map.layers.collisions[7 * width + 7] = 4; data.map.layers.collisions[8 * width + 7] = 5; const runtime = new PreviewRuntime(data); runtime.placePlayerAt(60, 64); const up = { left: false, right: false, up: true, down: false, action: false }; runtime.step(up); runtime.step(up); assert.ok(runtime.bodies.find((body) => body.key === "player").frame > 0); runtime.step(); assert.equal(runtime.bodies.find((body) => body.key === "player").frame, 0); });
test("chaser enemies align their whole collision box before descending", () => { const data = structuredClone(level); data.map.layers.collisions[7 * width + 7] = 4; data.map.layers.collisions[8 * width + 7] = 5; data.entities.enemies = [{ id: 10, x: 51, y: 43, bb_x: 0, bb_y: 0, bb_width: 10, bb_height: 21, direction: "right", speed_x: 1, speed_y: 3, ia_type: "chaser", ia_orig_x: 0, ia_orig_y: 0, ia_limit_x: 120, ia_limit_y: 100 }]; const runtime = new PreviewRuntime(data); runtime.setInvulnerable(true); runtime.placePlayerAt(60, 80); runtime.step(); const enemy = runtime.bodies.find((body) => body.key === "enemies:10"); assert.equal(enemy.x, 55); assert.equal(enemy.y, 43); });
test("chaser enemies climb stairs when the player is above", () => { const data = structuredClone(level); for (const row of [6, 7]) data.map.layers.collisions[row * width + 7] = 4; data.map.layers.collisions[8 * width + 7] = 5; data.entities.enemies = [{ id: 7, x: 56, y: 51, bb_x: 0, bb_y: 0, bb_width: 8, bb_height: 21, direction: "right", speed_x: 1, speed_y: 3, ia_type: "chaser", ia_orig_x: 0, ia_orig_y: 0, ia_limit_x: 120, ia_limit_y: 100 }]; const runtime = new PreviewRuntime(data); runtime.setInvulnerable(true); runtime.step(); const enemy = runtime.bodies.find((body) => body.key === "enemies:7"); assert.equal(enemy.x, 56); assert.equal(enemy.y, 49); });
test("chaser enemies leave climbing state after passing the end of a ladder", () => { const data = structuredClone(level); data.map.layers.collisions[7 * width + 7] = 4; data.map.layers.collisions[8 * width + 7] = 5; data.entities.enemies = [{ id: 15, x: 56, y: 51, bb_x: 0, bb_y: 0, bb_width: 8, bb_height: 21, direction: "right", speed_x: 1, speed_y: 3, ia_type: "chaser", ia_orig_x: 0, ia_orig_y: 0, ia_limit_x: 120, ia_limit_y: 100 }]; const runtime = new PreviewRuntime(data); runtime.setInvulnerable(true); runtime.placePlayerAt(100, 32); for (let i = 0; i < 12; ++i) runtime.step(); assert.equal(runtime.bodies.find((body) => body.key === "enemies:15").state, "CHAR_STATE_RUNNING"); });
test("a ladder top ends climbing and places the enemy on its upper edge", () => { const data = structuredClone(level); data.map.layers.collisions[7 * width + 7] = 5; data.map.layers.collisions[8 * width + 7] = 4; data.entities.enemies = [{ id: 16, x: 56, y: 51, bb_x: 0, bb_y: 0, bb_width: 8, bb_height: 21, direction: "right", speed_x: 1, speed_y: 3, ia_type: "chaser", ia_orig_x: 0, ia_orig_y: 0, ia_limit_x: 120, ia_limit_y: 100 }]; const runtime = new PreviewRuntime(data); runtime.setInvulnerable(true); runtime.placePlayerAt(100, 24); for (let i = 0; i < 8; ++i) runtime.step(); const enemy = runtime.bodies.find((body) => body.key === "enemies:16"); assert.equal(enemy.state, "CHAR_STATE_RUNNING"); assert.equal(enemy.y, 35); });
test("a chaser stops climbing when Rick leaves its IA zone", () => { const data = structuredClone(level); for (const row of [6, 7]) data.map.layers.collisions[row * width + 7] = 4; data.map.layers.collisions[8 * width + 7] = 5; data.entities.enemies = [{ id: 17, x: 56, y: 51, bb_x: 0, bb_y: 0, bb_width: 8, bb_height: 21, direction: "right", speed_x: 1, speed_y: 3, ia_type: "chaser", ia_orig_x: 0, ia_orig_y: 0, ia_limit_x: 100, ia_limit_y: 100 }]; const runtime = new PreviewRuntime(data); runtime.setInvulnerable(true); runtime.placePlayerAt(60, 40); runtime.step(); assert.equal(runtime.bodies.find((body) => body.key === "enemies:17").state, "CHAR_STATE_CLIMBING"); runtime.placePlayerAt(150, 40); runtime.step(); assert.equal(runtime.bodies.find((body) => body.key === "enemies:17").state, "CHAR_STATE_RUNNING"); });
test("chaser enemies center on stairs when a side of the box hits the ceiling", () => { const data = structuredClone(level); for (const row of [5, 6, 7, 8]) for (const column of [7, 8]) data.map.layers.collisions[row * width + column] = row === 8 ? 5 : 4; data.map.layers.collisions[5 * width + 6] = 2; data.entities.enemies = [{ id: 12, x: 54, y: 43, bb_x: 0, bb_y: 0, bb_width: 10, bb_height: 21, direction: "right", speed_x: 1, speed_y: 3, ia_type: "chaser", ia_orig_x: 0, ia_orig_y: 0, ia_limit_x: 120, ia_limit_y: 100 }]; const runtime = new PreviewRuntime(data); runtime.setInvulnerable(true); runtime.placePlayerAt(60, 40); runtime.step(); const enemy = runtime.bodies.find((body) => body.key === "enemies:12"); assert.equal(enemy.x, 56); assert.equal(enemy.y, 43); });
test("falling enemies snap onto the floor instead of flipping while embedded", () => { const data = structuredClone(level); data.entities.enemies = [{ id: 14, x: 40, y: 40, bb_x: 0, bb_y: 0, bb_width: 10, bb_height: 21, direction: "right", speed_x: 1, speed_y: 3, ia_type: "chaser", ia_orig_x: 0, ia_orig_y: 0, ia_limit_x: 120, ia_limit_y: 100 }]; const runtime = new PreviewRuntime(data); runtime.setInvulnerable(true); runtime.placePlayerAt(100, 64); for (let i = 0; i < 12; ++i) runtime.step(); const enemy = runtime.bodies.find((body) => body.key === "enemies:14"); assert.equal(enemy.y, 43); assert.ok(enemy.x > 40); });
test("enemy contact consumes a life", () => { const data = structuredClone(level); data.entities.enemies = [{ id: 3, x: 22, y: 43, bb_x: 0, bb_y: 0, bb_width: 10, bb_height: 21, direction: "right", speed_x: 0, speed_y: 3, ia_type: "walker" }]; const runtime = new PreviewRuntime(data); runtime.step(); assert.equal(runtime.player.state, "dead"); assert.equal(runtime.lives, 2); });
test("a correctly faced hit freezes an enemy and its animation instead of killing Rick", () => { const data = structuredClone(level); data.entities.enemies = [{ id: 4, x: 24, y: 43, bb_x: 0, bb_y: 0, bb_width: 10, bb_height: 21, direction: "right", speed_x: 1, speed_y: 3, ia_type: "walker" }]; const runtime = new PreviewRuntime(data); const hitRight = { left: false, right: true, up: false, down: false, action: true }; runtime.step(hitRight); const frozen = runtime.bodies.find((body) => body.key === "enemies:4"); runtime.step(); const after = runtime.bodies.find((body) => body.key === "enemies:4"); assert.equal(runtime.player.state === "dead", false); assert.equal(after.x, frozen.x); assert.equal(after.frame, frozen.frame); });
test("a frozen enemy flashes every four ticks while retaining its debug body", () => { const data = structuredClone(level); data.entities.enemies = [{ id: 41, x: 24, y: 43, bb_x: 0, bb_y: 0, bb_width: 10, bb_height: 21, direction: "right", speed_x: 1, speed_y: 3, ia_type: "walker" }]; const runtime = new PreviewRuntime(data); runtime.step({ left: false, right: true, up: false, down: false, action: true }); assert.equal(runtime.bodies.find((body) => body.key === "enemies:41").spriteVisible, true); for (let i = 0; i < 4; ++i) runtime.step(); const flashing = runtime.bodies.find((body) => body.key === "enemies:41"); assert.equal(flashing.spriteVisible, false); assert.equal(flashing.width, 10); });
test("shots kill enemies", () => { const data = structuredClone(level); data.entities.enemies = [{ id: 5, x: 43, y: 51, bb_x: 0, bb_y: 0, bb_width: 10, bb_height: 8, direction: "right", speed_x: 0, speed_y: 0, ia_type: "walker" }]; const runtime = new PreviewRuntime(data); runtime.setInvulnerable(true); runtime.step({ left: false, right: false, up: true, down: false, action: true }); runtime.step(); assert.equal(runtime.bodies.some((body) => body.key === "enemies:5"), false); });
